// Helper that acts as controller (msg.sender) to call C.initialize and set oracle to our fake oracle.
contract ControllerHelper {
    C immutable c;
    FakeOracle immutable oracle;
    constructor(C c_, FakeOracle o_) {
        c = c_;
        oracle = o_;
    }

    // Build minimal ProductInfo ABI and call initialize on C as the controller
    function callInitialize(uint256 version_, uint256 timestamp_, int256 price_) external {
        // Construct a minimal PayoffDefinition and ProductInfo with required fields.
        // Many types are complex; instead we call C.initialize with tightly packed encoded data where
        // payoffDefinition is zeroed and other numeric fields are zero; only oracle address is important.
        // Build ProductInfo tuple per C source ordering:
        // (string name, string symbol, PayoffDefinition payoffDefinition, IOracleProvider oracle, UFixed18 maintenance,
        //  UFixed18 fundingFee, UFixed18 makerFee, UFixed18 takerFee, UFixed18 positionFee, UFixed18 makerLimit,
        //  JumpRateUtilizationCurve utilizationCurve)
        // We'll supply empty strings and zeros, and set oracle address to our fake oracle.

        bytes memory name = abi.encode("n");
        bytes memory symbol = abi.encode("s");
        // payoffDefinition as empty 32 bytes
        bytes memory payoffDefinition = abi.encodePacked(new bytes(0));

        // Build ABI for initialize(ProductInfo)
        // Use high-level call via C.initialize by constructing a struct in Solidity is hard here; instead call via
        // try-catch on c.initialize with dummy values using low-level abi.encodeWithSelector.

        // We craft a call where most complex nested structs are zeroed by using default values.
