        // ProductInfo type; however types are declared in C; direct creation here by encoding is acceptable if fields align.

        // We'll call initialize with name="n", symbol="s", payoffDefinition = zeros (30 bytes), oracle = address(oracle),
        // and zeros for the rest. Use abi.encodeWithSignature to avoid needing exact type names for nested library types.

        bytes memory data = abi.encodeWithSignature(
            "initialize((string,string,(uint8,bytes30),address,uint256,uint256,uint256,uint256,uint256,uint256,(int128,int128,int128,uint128)))",
            "n",
            "s",
            // dummy PayoffDefinition: we pass tuple matching (PayoffType, PayoffDirection, bytes30) encoded as (uint8,bytes30)
            (uint8(0), bytes30(0)),
            address(oracle),
            uint256(0), uint256(0), uint256(0), uint256(0), uint256(0), uint256(0),
            // JumpRateUtilizationCurve placeholder: (PackedFixed18 minRate, PackedFixed18 maxRate, PackedFixed18 targetRate, PackedUFixed18 targetUtilization)
            (int128(0), int128(0), int128(0), uint128(0))
        );

        (bool success, ) = address(c).call(data);
        require(success, "init failed");
    }
}

