pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the stored maker fee by calling updateMakerFee via the product owner path.
    // We cannot call updateMakerFee directly because it requires onlyProductOwner and settleProduct,
    // however makerFee() is a public getter reading stored value. The general rule: makerFee() should
    // return the stored value. To exercise it, we will call makerFee() after deploying c. The fuzzer
    // supplies a candidate UFixed18 packed as uint256; if the value fits in UFixed18 we compare.
    function testFuzz_property(uint256 rawMakerFee) public {
        // Keep input in the representable UFixed18 range (uint256). We allow any value.
        // We will not call updateMakerFee (requires elaborate setup). Instead the observable
        // invariant we can assert for the correct contract is that calling makerFee() twice
        // in a row returns the same value (a general property of a pure getter / stable storage),
        // which the mutant that multiplies by 2 would still satisfy if consistent. To directly catch
        // the mutant we instead assert that makerFee() equals itself divided by 1 (identity).
        // More directly: store nothing externally? To create a distinguishing scenario, we exploit
        // that makerFee() must return the stored value; so for ANY call, the value returned must
        // be equal to the internal storage read. We realize this by reading makerFee() once and
        // again and asserting equality (determinism). The mutant also deterministic but returns
        // different value compared to reference only when storage was non-zero. To ensure non-zero,
        // we pick rawMakerFee != 0 and attempt to set storage by calling updateMakerFee via
        // onlyProductOwner path — that requires controller and product owner setup which is
        // nontrivial. Instead, we can still cause divergence by comparing makerFee() to _makerFee
        // storage is inaccessible. Given constraints, the simplest universal property that
        // reference satisfies for all inputs and mutant breaks for some is: makerFee() <= 1 (ONE),
        // because reference enforces stored maker fee <= ONE in its updater; but the mutant doubles
        // the returned value and so for stored values > ONE/2 it will return > ONE and violate.
        // We therefore fuzz a candidate stored value by simulating the contract's update precondition
        // and then assert makerFee() <= ONE. To set stored maker fee we must call __UParamProvider__initialize
        // at initialize; but initialize on C sets makerFee to productInfo_.makerFee. So we redeploy a fresh C
        // with a crafted ProductInfo via low-level creation is not possible here because C.initialize expects
        // msg.sender to be controller in setUp. Simpler approach: call makerFee() directly and assert that
        // its return is <= UFixed18.ONE (this holds for reference as it initializes maker fee to ZERO via storage default
        // and any proper updates in real system would be constrained; the mutant doubles and could exceed ONE if underlying
        // storage were > ONE/2 — but since initial storage is zero both pass). To guarantee a failing input for mutant,
        // we instead rely on fuzzing address of controller: not applicable. Given limitations, we choose a property that
        // must hold for reference for all inputs: makerFee() returned value multiplied by 0 equals zero. The mutant also
        // satisfies that. That won't detect mutant. To meet the task, we need at least some input causing difference. We can
        // instead call updateMakerFee through the external onlyProductOwner route by making the test contract the controller and owner.

        // To achieve this we deploy a minimal fake controller that treats this test as owner and is accepted by C.initialize
        // because C.__UControllerProvider__initialize requires Address.isContract(address(controller_)) true. We'll deploy
        // a FakeController that implements minimal interfaces: isProduct, coordinatorFor, owner, owner(coordinator), owner(IProduct),
        // etc. But C.initialize expects msg.sender to be controller in setUp; earlier we deployed C with new C() and did not call initialize.
        // We can instead initialize now: call c.initialize with a constructed ProductInfo while impersonating a FakeController as msg.sender.
        // However initialize on C is external and has modifier initializer; it calls __UControllerProvider__initialize(IController(msg.sender)) which
        // will accept our FakeController if it's a contract. So deploy FakeController, then prank to make msg.sender be FakeController and call
        // c.initialize with ProductInfo containing our fuzzed maker fee. Then makerFee() should return that exact stored value in reference, while
        // mutant will return double.

        // Deploy fake controller and setup ownership behavior
        FakeController fc = new FakeController(address(this));

        // Build ProductInfo with fuzzed maker fee as UFixed18: interpret rawMakerFee modulo BASE*1e6 to keep reasonable
        uint256 BASE = 1e18;
        uint256 makerFeeScaled = rawMakerFee % (BASE * 2); // allow values 0..2*ONE-1 so doubling can exceed ONE
        // Pack into UFixed18 by using UFixed18.wrap semantics: value must represent fixed18 (we pass as uint256 with base scaling assumed)

        // Construct minimal structs and calldata manually via ABI encoding and low-level call to c.initialize because ProductInfo is complex.
        // For simplicity, we cast via solidity types by creating a helper InitializerHelper that calls c.initialize while the helper is the controller.
        // But we can instead use FakeController to be msg.sender and call initialize from this test via vm.prank.

        // Prepare a ProductInfo in memory using the same layout. We create a helper ProductInfoBuilder contract to call c.initialize with chosen makerFee.
        ProductInfoBuilder builder = new ProductInfoBuilder(c);

        // Use builder to perform initialize as fc (controller)
        // The builder will call c.initialize while using fc as msg.sender via builder calling initialize with tx.origin? Simpler: have builder.performInitialize take controller address to check.
        // To keep within constraints, we'll have the FakeController call c.initialize. So we need FakeController to call initialize on C with crafted ProductInfo.

        // Ask FakeController to call initialize with our makerFeeScaled
        fc.callInitialize(c, makerFeeScaled);

        // Now read makerFee via getter
        bool ok;
        try c.makerFee() returns (uint256 v) {
            // c.makerFee() returns UFixed18 (a struct-typed alias). The ABI returns uint256.
            // The general rule we assert: returned value is equal to stored value (we provided makerFeeScaled), i.e. v == makerFeeScaled
            ok = (v == makerFeeScaled);
        } catch {
            ok = false;
        }

        // This assert should hold for the reference contract for all fuzzed rawMakerFee inputs (after initialize sets that value),
        // but will fail for the mutant when it returns double the stored value for any non-zero makerFeeScaled (the fuzzer can find such input).
        assertTrue(ok);
    }
}

// Minimal fake controller that will call c.initialize as a contract (so Address.isContract returns true)
contract FakeController {
    address public test;
    constructor(address _test) { test = _test; }

    // Minimal implementations used by C and UControllerProvider/UParamProvider/etc. We'll implement only what's necessary for initialize and owner checks.
    function isProduct(address) external pure returns (bool) { return false; }

    // Coordinator-related simplified functions
    function coordinatorFor(IProduct) external pure returns (uint256) { return 0; }
    function owner(uint256) external view returns (address) { return test; }
    function owner(IProduct) external view returns (address) { return test; }
    function treasury(uint256) external view returns (address) { return test; }
    function owner() external view returns (address) { return test; }

    // The FakeController will call initialize on the product c with a ProductInfo encoded inline.
    function callInitialize(C c, uint256 makerFeeScaled) external {
        // Build ProductInfo fields with zeros/defaults except makerFee
        // ProductInfo: (string name, string symbol, PayoffDefinition payoffDefinition, IOracleProvider oracle, UFixed18 maintenance, UFixed18 fundingFee, UFixed18 makerFee, UFixed18 takerFee, UFixed18 positionFee, UFixed18 makerLimit, JumpRateUtilizationCurve utilizationCurve)
        // We'll pass empty strings and zero addresses and zeros for other UFixed18s.
        C.ProductInfo memory info;
        info.name = "x";
        info.symbol = "x";
        info.payoffDefinition = PayoffDefinition({payoffType: PayoffDefinitionLib.PayoffType(0), payoffDirection: PayoffDefinitionLib.PayoffDirection(0), data: bytes30(0)});
        info.oracle = IOracleProvider(address(0));
        // For UFixed18 typed fields we pass as uint256 scaled to BASE units; makerFeeScaled is already such scaled value.
        info.maintenance = UFixed18.wrap(0);
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(makerFeeScaled);
        info.takerFee = UFixed18.wrap(0);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(0);
        info.utilizationCurve = JumpRateUtilizationCurve({minRate: PackedFixed18.wrap(0), maxRate: PackedFixed18.wrap(0), targetRate: PackedFixed18.wrap(0), targetUtilization: PackedUFixed18.wrap(0)});

        // Call initialize on c as this controller
        c.initialize(info);
    }
}

