// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 rawMakerFee) public {
        // keep rawMakerFee in a wide admissible domain but within UFixed18 packing range
        // UFixed18.wrap expects a uint256 representing value*1e18; many functions expect UFixed18 values.
        // We'll bound to something reasonable: up to 1e30 to avoid overflow in typical mul operations in library
        uint256 bounded = bound(rawMakerFee, 0, 1e30);

        // Construct a ProductInfo with the fuzzed makerFee and minimal viable values for other fields.
        // We need to call initialize on the product; initialize requires being called by an IController (msg.sender).
        // The contract's initialize uses msg.sender as controller; we can deploy a dummy controller that satisfies required interfaces minimally.
        // However the test harness constraint forbids adding other test functions; we can reuse a small local Controller stub deployed here.
        ControllerStub ctrl = new ControllerStub();

        // prepare ProductInfo struct in memory via ABI encoding then ABI decoding to the expected type
        // But solidity doesn't allow constructing complex calldata types easily here without redeclaring types.
        // Instead, call initialize through a low-level call from the controller stub which will forward the call as if msg.sender is the controller.

        // Build minimal ProductInfo ABI-encoded payload matching C.ProductInfo layout from the source.
        // Types: string name, string symbol, PayoffDefinition payoffDefinition (3 fields), IOracleProvider oracle (address),
        // UFixed18 maintenance, UFixed18 fundingFee, UFixed18 makerFee, UFixed18 takerFee, UFixed18 positionFee, UFixed18 makerLimit,
        // JumpRateUtilizationCurve utilizationCurve (4 fields: int128 minRate,int128 maxRate,int128 targetRate,uint128 targetUtilization)

        // For simplicity, encode strings as empty, payoffDefinition as zeros (bytes30 zeros, enum zeros), oracle address zero,
        // all UFixed18 fields set to bounded, and utilization curve zeros.

        // Helper to wrap uint256 into UFixed18: it's just uint256 value representing fixed*1e18. We use bounded directly.

        bytes memory name = bytes("");
        bytes memory symbol = bytes("");
        // PayoffDefinition: two enums (as uint8) and bytes30 -> total 32 bytes -> we provide zeros
        bytes32 payoff_def_bytes32 = bytes32(0);
        address oracle = address(0);
        uint256 maintenance = bounded;
        uint256 fundingFee = bounded;
        uint256 makerFee = bounded;
        uint256 takerFee = bounded;
        uint256 positionFee = bounded;
        uint256 makerLimit = bounded;
        // utilization curve: minRate,maxRate,targetRate as int128, targetUtilization as uint128
        int128 minRate = 0;
        int128 maxRate = 0;
        int128 targetRate = 0;
        uint128 targetUtilization = 0;

        bytes memory encoded = abi.encode(
            name,
            symbol,
            payoff_def_bytes32,
            oracle,
            maintenance,
            fundingFee,
            makerFee,
            takerFee,
            positionFee,
            makerLimit,
            minRate,
            maxRate,
            targetRate,
            targetUtilization
        );

        // Now have controller perform the initialize call as if it were msg.sender
        // prepare calldata: initialize(ProductInfo)
        bytes memory sig = abi.encodeWithSignature("initialize((string,string,bytes30,address,uint256,uint256,uint256,uint256,uint256,uint256,int128,int128,int128,uint128))", encoded);
        // ControllerStub will call c.initialize with provided calldata forwarded from the stub
        ctrl.forwardInit(address(c), encoded);

        // Now the product is initialized with makerFee = bounded (stored value). Query makerFee via the public getter.
        // Use try/catch to capture any revert (though getter is view and should not revert)
        bool ok;
        uint256 returnedRaw;
        try c.makerFee() returns (uint256 v) {
            ok = true;
            returnedRaw = v;
        } catch {
            ok = false;
            returnedRaw = 0;
        }

        // The general rule: the getter returns exactly the stored maker fee value. We observe stored value via making no other modification
        // Since our initialize stored 'makerFee' as 'bounded', the returnedRaw must equal bounded for the reference.
        // The mutant doubles the returned value for some bounded > 0.
        assertTrue(ok && returnedRaw == bounded);
    }
}

// Minimal Controller stub that simply calls initialize on the product (so msg.sender in initialize is this controller)
contract ControllerStub {
    function forwardInit(address product, bytes memory encodedProductInfo) public {
        // Recreate the ProductInfo tuple decoding to build correct calldata to call initialize
        // We directly abi.decode the encodedProductInfo as the components we encoded in test
        (bytes memory name,
         bytes memory symbol,
         bytes32 payoff_def_bytes32,
         address oracle,
         uint256 maintenance,
         uint256 fundingFee,
         uint256 makerFee,
         uint256 takerFee,
         uint256 positionFee,
         uint256 makerLimit,
         int128 minRate,
         int128 maxRate,
         int128 targetRate,
         uint128 targetUtilization) = abi.decode(encodedProductInfo, (bytes,bytes,bytes32,address,uint256,uint256,uint256,uint256,uint256,uint256,int128,int128,int128,uint128));

        // Re-encode into the actual ProductInfo struct as calldata
        bytes memory payoffDefinitionPacked = abi.encodePacked(uint8(0), uint8(0), bytes30(0));
        bytes memory utilizationCurvePacked = abi.encode(minRate, maxRate, targetRate, targetUtilization);

        // Build ProductInfo tuple via abi.encode
        bytes memory productInfo = abi.encode(
            name,
            symbol,
            abi.decode(payoffDefinitionPacked, (bytes30)),
            oracle,
            maintenance,
            fundingFee,
            makerFee,
            takerFee,
            positionFee,
            makerLimit,
            abi.decode(utilizationCurvePacked, (int128)),
            abi.decode(utilizationCurvePacked, (int128)),
            abi.decode(utilizationCurvePacked, (int128)),
            abi.decode(utilizationCurvePacked, (uint128))
        );

        // call initialize on the product as this controller
        (bool s, ) = product.call(abi.encodeWithSignature("initialize((string,string,bytes30,address,uint256,uint256,uint256,uint256,uint256,uint256,int128,int128,int128,uint128))", productInfo));
        require(s, "init failed");
    }
}
